/*
 * Reads one operand from the camera script and advances the cursor; a negative operand -k reads
 * element k of g_BattleSummonIfritMeshState.table instead.
 */
// FUNCTION: FF7 0x0059397c
short __cdecl BattleFx_IfritReadCameraScriptOperand(short **cursorPtr)
{
    int operand;

    operand = **cursorPtr;
    (*cursorPtr)++;
    if (operand < 0) {
        operand = g_BattleSummonIfritMeshState.table[-operand];
    }
    return (short)operand;
}

/*
 * Applies easing interpolation to camera script coordinates.
 */
// FUNCTION: FF7 0x005939b6
int __cdecl BattleFx_IfritApplyCameraEasing(int value, int easeAmount)
{
    int i;
    int origValue;
    int passes;

    origValue = value;
    if (easeAmount > 0) {
        passes = easeAmount >> 8;
        for (i = 0; i < passes; i++) {
            value = SinFixed(value / 4);
        }
    } else {
        easeAmount = -easeAmount;
        passes = easeAmount >> 8;
        value = 0x1000 - value;
        for (i = 0; i < passes; i++) {
            value = SinFixed(value / 4);
        }
        value = 0x1000 - value;
    }
    passes = (easeAmount & 0xFF) + 1;
    value = (value * passes + origValue * (0x100 - passes)) >> 8;
    return value;
}

/*
 * Main timeline task controlling Ifrit animation, fire effects, and camera.
 */
// FUNCTION: FF7 0x00593a95
void __cdecl BattleFx_SummonIfritTimelineTask(void)
{
    int stage;
    BattleFxSummonIfritRingRecord *ringRecord;
    BattleTaskSlot *taskPtr;
    int i;
    BattleFxIfritTimeline *pSubtask;

    taskPtr = BATTLE_CURRENT_TASK_SLOT;
    if ((g_BattleSummonIfritTimelineReady & 1) == 0) {
        g_BattleSummonIfritTimelineReady |= 1;
        g_BattleSummonIfritTimelineState = (BattleFxIfritTimelineState *)Gfx_GetPsxScratchpadPtr(0);
    }
    MultiplyMatrix(&g_BattleCameraTransform, g_BattleSummonIfritRotMatrix, &g_BattleSummonIfritViewMatrix);
    if (g_BattleIsPaused != 0) {
        return;
    }
    stage = taskPtr->frameCounter;
    if (stage < 4) {
        if (stage == 0) {
            Battle_StartFixedPointRamp(0x400, 4);
            g_BattleFxTimelineState.red = 0x80;
            g_BattleFxTimelineState.channel1 = 0;
            g_BattleFxTimelineState.channel2 = 0;
        }
    } else {
        stage -= 4;
        if (stage < 10) {
            if (stage == 0) {
                Battle_AllocateResourceSlot(BattleFx_SummonIfritMorphMeshTask);
                Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_3, 0x40, 0);
            }
        } else {
            stage -= 10;
            if (stage < 10) {
                if (stage == 0) {
                    ringRecord = (BattleFxSummonIfritRingRecord *)Battle_AllocSceneMessage(1);
                    ringRecord->rotX = *(short *)((char *)&g_BattleSummonIfritRotMatrix + 18);
                    ringRecord->rotY = *(short *)((char *)&g_BattleSummonIfritRotMatrix + 22);
                    ringRecord->rotZ = *(short *)((char *)&g_BattleSummonIfritRotMatrix + 26);
                    ringRecord->angleY = g_BattleSummonIfritFacingAngles[1] ^ 0x800;
                    Battle_AllocateResourceSlot(BattleFx_SummonIfritGrowFadeModelTask);
                    Battle_AllocateResourceSlot(BattleFx_SummonIfritTwinRotatingModelTask);
                    Battle_AllocateResourceSlot(BattleFx_SummonIfritMoveSummonActorTask);
                }
            } else {
                stage -= 10;
                if (stage < 20) { /* empty first arm: lib/codegen.h */
                } else {
                    stage -= 20;
                    if (stage < 50) {
                        if (stage == 0) {
                            Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_3, 0x40, 1);
                        }
                        if (stage < 5) {
                            pSubtask = (BattleFxIfritTimeline *)BATTLE_NEW_TASK_SLOT(BattleFx_SummonIfritPulsingFadeModelTask);
                            pSubtask->posX = 0;
                            pSubtask->posY = rand() % 1000 - 3500;
                            pSubtask->posZ = 0;
                            pSubtask->shakeX = 0;
                            pSubtask->shakeY = rand() & 0xFFF;
                            pSubtask->shakeZ = 0;
                            pSubtask->scale = rand() % 0x80 + 0x180;
                        }
                    } else {
                        stage -= 50;
                        if (stage < 21) {
                            if (stage == 0) {
                                Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_3, 0x40, 2);
                                Sfx_ReleaseCachedBuffer(0x1AC, 0);
                                Sfx_ReleaseCachedBuffer(0x1AD, 0);
                                Sfx_ReleaseCachedBuffer(0x1AE, 0);
                            }
                        } else {
                            stage -= 21;
                            if (stage < 29) {
                                Battle3d_GetActorAttachMatrix(3, 5, (PsxMatrix *)((int)g_BattleActorRecords[3].boneNodes5));
                                Battle_ComposeMatrixRelativeToCamera((short *)&g_BattleCameraTransform, g_BattleActorRecords[3].boneNodes5, (PsxMatrix *)g_BattleSummonIfritTimelineState);
                                SetRotMatrix((void *)g_BattleSummonIfritTimelineState);
                                SetTransMatrix(g_BattleSummonIfritTimelineState);
                                RotTransPoint(&g_BattleSummonIfritActorMoveParams, (char *)g_BattleSummonIfritTimelineState + 0x1E, (char *)g_BattleSummonIfritTimelineState + 0x30);
                                for (i = 0; i < 2; i++) {
                                    pSubtask = (BattleFxIfritTimeline *)BATTLE_NEW_TASK_SLOT(BattleFx_SummonIfritBillboardSpriteTask);
                                    pSubtask->posX = g_BattleSummonIfritTimelineState->transformedX;
                                    pSubtask->posY = g_BattleSummonIfritTimelineState->transformedY;
                                    pSubtask->posZ = g_BattleSummonIfritTimelineState->transformedZ;
                                    pSubtask->shakeX = g_BattleSummonIfritActorShakeParams[i].x + rand() % 10 + -5;
                                    pSubtask->shakeY = g_BattleSummonIfritActorShakeParams[i].y + rand() % 10 + -5;
                                    pSubtask->shakeZ = g_BattleSummonIfritActorShakeParams[i].z + rand() % 10 + -5;
                                    pSubtask->scale = rand() % 0x200 + 0x200;
                                }
                            } else {
                                stage -= 29;
                                if (stage < 18) {
                                    if (stage == 0) {
                                        Battle_AllocateResourceSlot(BattleFx_SummonIfritSpinningMeshTask);
                                    }
                                } else {
                                    stage -= 18;
                                    if (stage < 20) {
                                        if (stage == 0) {
                                            Battle_AllocateResourceSlot(BattleFx_SummonIfritDrawMeshSpawnParticlesTask);
                                        }
                                        if (stage == 0) {
                                            Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_3, 0x40, 3);
                                            Sfx_ReleaseCachedBuffer(0x1AF, 1);
                                            Sfx_ReleaseCachedBuffer(0x1B0, 1);
                                            Sfx_ReleaseCachedBuffer(0x1B1, 1);
                                        }
                                    } else {
                                        stage -= 20;
                                        if (stage < 15) {
                                            if (stage == 0) {
                                                Battle_AllocateResourceSlot(BattleFx_SummonIfritSpawnAnimatedSpritesTask);
                                                ringRecord = (BattleFxSummonIfritRingRecord *)Battle_AllocSceneMessage(2);
                                            }
                                        } else {
                                            stage -= 15;
                                            if (stage < 15) {
                                                if (stage == 0) {
                                                    for (i = 0; i < 10; i++) {
                                                        if ((g_BattleSummonIfritTargetMask & 1 << i) != 0) {
                                                            Battle_PostActorHitOrHurtMessage(i);
                                                        }
                                                    }
                                                    Battle_AllocateResourceSlot(BattleFx_SummonIfritScreenStripWarpTask);
                                                }
                                            } else {
                                                Battle_StartFixedPointRamp(0, 4);
                                                g_BattleStageHideFlags = 0;
                                                taskPtr->ownerSlot = BATTLE_TASK_FREE;
                                                if (g_BattleSummonIfritWarpSlot1 >= 0) {
                                                    Battle3d_ReleaseOffscreenSlot(g_BattleSummonIfritWarpSlot1);
                                                    g_BattleSummonIfritWarpSlot1 = 0xFFFFFFFF;
                                                }
                                                if (g_BattleSummonIfritWarpSlot2 >= 0) {
                                                    Battle3d_ReleaseOffscreenSlot(g_BattleSummonIfritWarpSlot2);
                                                    g_BattleSummonIfritWarpSlot2 = 0xFFFFFFFF;
                                                }
                                                if (g_BattleSummonIfritWarpSlot3 >= 0) {
                                                    Battle3d_ReleaseOffscreenSlot(g_BattleSummonIfritWarpSlot3);
                                                    g_BattleSummonIfritWarpSlot3 = 0xFFFFFFFF;
                                                }
                                                Sfx_ReleaseCachedBuffer(0x1B2, 2);
                                                Sfx_ReleaseCachedBuffer(0x1B3, 2);
                                                Sfx_ReleaseCachedBuffer(0x1B4, 2);
                                                Sfx_ReleaseCachedBuffer(0x1B5, 3);
                                                Sfx_ReleaseCachedBuffer(0x1B6, 3);
                                                Sfx_ReleaseCachedBuffer(0x1B7, 3);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    (taskPtr->frameCounter)++;
}

/*
 * Morphs Ifrit body mesh vertices across keyframe poses.
 */
// FUNCTION: FF7 0x005940b2
void __cdecl BattleFx_SummonIfritMorphMeshTask(void)
{
    int frameCount;
    BattleFxPhaseControllerTask *task;
    int vertexIndex;
    SVECTOR *pSrcPose;
    SVECTOR *cur;
    void *dataBlock;

    task = (BattleFxPhaseControllerTask *)BATTLE_CURRENT_TASK_SLOT;
    dataBlock = (void *)Gfx_GetPsxScratchpadPtr(0);
    frameCount = task->frameCount;
    if (frameCount < 10) {
        g_BattleSummonIfritModelIndices1[0] = (frameCount << 12) / 10;
        g_BattleSummonIfritScaleParam1 = g_BattleSummonIfritModelIndices1[0];
        g_BattleSummonIfritModelScale1[0] = g_BattleSummonIfritScaleParam1;
    } else {
        frameCount -= 10;
        if (frameCount < 30) {
            g_BattleSummonIfritModelIndices1[0] = 0x1000;
            g_BattleSummonIfritScaleParam1 = g_BattleSummonIfritModelIndices1[0];
            g_BattleSummonIfritModelScale1[0] = g_BattleSummonIfritScaleParam1;
        } else {
            task->stage = BATTLE_TASK_FREE;
            return;
        }
    }
    MultiplyMatrix(g_BattleSummonIfritRotMatrix, g_BattleSummonIfritModelScale1, dataBlock);
    MultiplyMatrix(&g_BattleCameraTransform, dataBlock, dataBlock);
    SetRotMatrix(dataBlock);
    SetTransMatrix(dataBlock);
    (*(int *)&g_BattleSummonIfritModelColor1) = Gfx_ModelTableGetRenderObject(0, g_BattleSummonIfritLoadedRes);
    RefreshGlobalTransformState();
    Gfx_SetPsxPrimQuadState(9, 4, (GfxPsxSpriteQuadState *)(Gfx_ModelTableGetSpriteObject(19, g_BattleSummonIfritLoadedRes)));
    Gfx_SetPsxPrimQuadState(9, 1, (GfxPsxSpriteQuadState *)(Gfx_ModelTableGetSpriteObject(20, g_BattleSummonIfritLoadedRes)));
    Gfx_SetPsxPrimQuadState(0xB, 4, (GfxPsxSpriteQuadState *)(Gfx_ModelTableGetSpriteObject(21, g_BattleSummonIfritLoadedRes)));
    Gfx_SetPsxPrimQuadState(0xB, 1, (GfxPsxSpriteQuadState *)(Gfx_ModelTableGetSpriteObject(22, g_BattleSummonIfritLoadedRes)));
    g_BattleOverlayDrawListHead = BattleFx_SummonIfritDrawPsxMesh((BattleFxIfritPsxMesh *)&g_BattleSummonIfritModelReq1, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleOverlayDrawListHead);
    g_BattleOverlayDrawListHead = BattleFx_SubmitModelDraw((BattleFxModelDraw *)&g_BattleSummonIfritModelColor1, g_BattleCurrentOrderingTable + BATTLE_OT_SORTED_LAST, 0, g_BattleOverlayDrawListHead);
    if (g_BattleIsPaused == 0) {
        frameCount = task->frameCount;
        if (frameCount < 36) {
            if (frameCount % 4 == 0) {
                pSrcPose = (SVECTOR *)g_BattleSummonIfritMorphPoses[frameCount / 4];
                cur = (SVECTOR *)(((unsigned char *)g_BattleSummonIfritMeshSource1) + 4);
                for (vertexIndex = 0; vertexIndex < 202; vertexIndex++) {
                    g_BattleSummonIfritMeshVertexBuffer[vertexIndex].stepX = (pSrcPose->vx - cur->vx) / 4;
                    g_BattleSummonIfritMeshVertexBuffer[vertexIndex].stepY = (pSrcPose->vy - cur->vy) / 4;
                    g_BattleSummonIfritMeshVertexBuffer[vertexIndex].stepZ = (pSrcPose->vz - cur->vz) / 4;
                    pSrcPose++;
                    cur++;
                }
            }
            cur = (SVECTOR *)(((unsigned char *)g_BattleSummonIfritMeshSource1) + 4);
            for (vertexIndex = 0; vertexIndex < 202; vertexIndex++) {
                cur->vx += g_BattleSummonIfritMeshVertexBuffer[vertexIndex].stepX;
                cur->vy += g_BattleSummonIfritMeshVertexBuffer[vertexIndex].stepY;
                cur->vz += g_BattleSummonIfritMeshVertexBuffer[vertexIndex].stepZ;
                cur++;
            }
        }
        (task->frameCount)++;
    }
}

