/*
 * Animates summon actor world movement and leap trajectory for Ifrit.
 */
// FUNCTION: FF7 0x00596702
void __cdecl BattleFx_SummonIfritMoveSummonActorTask(void)
{
    int frameCount;
    BattleTaskSlot *task;

    task = BATTLE_CURRENT_TASK_SLOT;
    if ((g_BattleSummonIfritMoveReady & 1) == 0) {
        g_BattleSummonIfritMoveReady |= 1;
        g_BattleSummonIfritActorPosScratch = (BattleFxPosition3s *)Gfx_GetPsxScratchpadPtr(0);
    }
    if (g_BattleIsPaused != 0) {
        return;
    }
    frameCount = task->frameCounter;
    if (frameCount < 30) {
        g_BattleSummonIfritModelPosition[1] = frameCount * -0x7D0 / 30;
    } else {
        frameCount -= 30;
        if (frameCount < 100) { /* empty first arm: lib/codegen.h */
        } else {
            frameCount -= 100;
            if (frameCount < 15) {
                g_BattleSummonIfritModelPosition[0] = g_BattleSummonIfritModelPosition[0];
                g_BattleSummonIfritModelPosition[1] += -0xA;
                g_BattleSummonIfritModelPosition[2] += 0xFFEC;
            } else {
                frameCount -= 15;
                if (frameCount < 3) {
                    g_BattleSummonIfritModelPosition[0] = g_BattleSummonIfritModelPosition[0];
                    g_BattleSummonIfritModelPosition[1] += 0x3E8;
                    g_BattleSummonIfritModelPosition[2] += 0x7D0;
                } else {
                    frameCount -= 3;
                    if (frameCount < 20) {
                        g_BattleSummonIfritModelPosition[0] = 0;
                        g_BattleSummonIfritModelPosition[1] = 0x1F4;
                        g_BattleSummonIfritModelPosition[2] = frameCount * 30000 / 20 - 0x1388;
                    } else {
                        task->ownerSlot = BATTLE_TASK_FREE;
                        return;
                    }
                }
            }
        }
    }
    SetRotMatrix((PsxMatrix *)g_BattleSummonIfritRotMatrix);
    SetTransMatrix(g_BattleSummonIfritRotMatrix);
    RotTransPoint(&g_BattleSummonIfritModelPosition[0], (int *)g_BattleSummonIfritActorPosScratch, (char *)g_BattleSummonIfritActorPosScratch + 0x10);
    g_BattleActorRecords[3].posX = g_BattleSummonIfritActorPosScratch->posX;
    g_BattleActorRecords[3].posY = g_BattleSummonIfritActorPosScratch->posY;
    g_BattleActorRecords[3].posZ = g_BattleSummonIfritActorPosScratch->posZ;
    (task->frameCounter)++;
}

/*
 * Updates and renders spinning flame mesh for Ifrit.
 */
// FUNCTION: FF7 0x005968e3
void __cdecl BattleFx_SummonIfritSpinningMeshTask(void)
{
    int frameCount;
    BattleTaskSlot *task;
    int bytes;

    task = BATTLE_CURRENT_TASK_SLOT;
    if ((g_BattleSummonIfritSpinReady & 1) == 0) {
        g_BattleSummonIfritSpinReady |= 1;
        g_BattleSummonIfritSpinMatrix = (void *)Gfx_GetPsxScratchpadPtr(0);
    }
    bytes = ((task->frameCounter & 1) != 0 ? 0xFFFFF800 : 0) + 0x800;
    frameCount = task->frameCounter;
    if (frameCount < 15) {
        bytes = (bytes - 0x1000) * frameCount / 15 + 0x1000;
        if (g_BattleIsPaused == 0) {
            g_BattleSummonIfritMeshState.transX = g_BattleSummonIfritMeshState.transX;
            g_BattleSummonIfritMeshState.transY -= 10;
            g_BattleSummonIfritMeshState.transZ -= 20;
        }
    } else {
        frameCount -= 15;
        if (frameCount < 3) {
            bytes = 0;
            if (g_BattleIsPaused == 0) {
                g_BattleSummonIfritMeshState.transX = g_BattleSummonIfritMeshState.transX;
                g_BattleSummonIfritMeshState.transY += 1000;
                g_BattleSummonIfritMeshState.transZ += 2000;
            }
        } else {
            task->ownerSlot = BATTLE_TASK_FREE;
            return;
        }
    }
    RotMatrix((SVECTOR *)&g_BattleSummonIfritSpinAngles, (PsxMatrix *)&g_BattleSummonIfritMeshState);
    ScaleMatrix(&g_BattleSummonIfritMeshState, &g_BattleSummonIfritSpinScaleX);
    MultiplyMatrix(&g_BattleSummonIfritViewMatrix, &g_BattleSummonIfritMeshState, g_BattleSummonIfritSpinMatrix);
    SetRotMatrix(g_BattleSummonIfritSpinMatrix);
    SetTransMatrix(g_BattleSummonIfritSpinMatrix);
    SetDrawColorRGB(0, 0, 0);
    (*(short *)((char *)&g_BattleSummonIfritRotAngles1 + 10)) = bytes;
    RefreshGlobalTransformState();
    Gfx_SetPsxPrimQuadState(9, 4, (GfxPsxSpriteQuadState *)(Gfx_ModelTableGetSpriteObject(15, g_BattleSummonIfritLoadedRes)));
    Gfx_SetPsxPrimQuadState(9, 1, (GfxPsxSpriteQuadState *)(Gfx_ModelTableGetSpriteObject(16, g_BattleSummonIfritLoadedRes)));
    Gfx_SetPsxPrimQuadState(0xB, 4, (GfxPsxSpriteQuadState *)(Gfx_ModelTableGetSpriteObject(17, g_BattleSummonIfritLoadedRes)));
    Gfx_SetPsxPrimQuadState(0xB, 1, (GfxPsxSpriteQuadState *)(Gfx_ModelTableGetSpriteObject(18, g_BattleSummonIfritLoadedRes)));
    g_BattleOverlayDrawListHead = BattleFx_SummonIfritDrawPsxMesh((BattleFxIfritPsxMesh *)&g_BattleSummonIfritRotAngles1, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleOverlayDrawListHead);
    if (g_BattleIsPaused == 0) {
        (task->frameCounter)++;
        g_BattleSummonIfritSpinAngles.angleZ += (short)(task->frameCounter * 0x30 / 18 + 0x10);
        g_BattleSummonIfritSpinScaleZ = task->frameCounter * 0x700 / 15 + 0x100;
    }
}

/*
 * Updates and renders pulsing fade model for Ifrit.
 */
// FUNCTION: FF7 0x00596b7e
void __cdecl BattleFx_SummonIfritPulsingFadeModelTask(void)
{
    int frameCount;
    BattleFxIfritPulseState *task;
    int pulsePhase;

    task = (BattleFxIfritPulseState *)BATTLE_CURRENT_TASK_SLOT;
    if ((g_BattleSummonIfritPulseReady & 1) == 0) {
        g_BattleSummonIfritPulseReady |= 1;
        g_BattleSummonIfritPulseMatrix = (BattleFxIfritPulseMatrix *)Gfx_GetPsxScratchpadPtr(0);
    }
    (*(int *)&g_BattleSummonIfritSpriteDrawReq2) = Gfx_ModelTableGetRenderObject(13, g_BattleSummonIfritLoadedRes);
    frameCount = task->frame;
    if (frameCount < 10) {
        (((BattleFxModelDraw *)&g_BattleSummonIfritSpriteDrawReq2)->fadeLevel) = frameCount * -0x1000 / 0xA + 0x1000;
    } else {
        frameCount -= 10;
        if (frameCount < 10) {
            (((BattleFxModelDraw *)&g_BattleSummonIfritSpriteDrawReq2)->fadeLevel) = (frameCount << 12) / 0xA;
        } else {
            task->ownerSlot = BATTLE_TASK_FREE;
            return;
        }
    }
    pulsePhase = (task->frame << 12) / 20;
    g_BattleSummonIfritPulseMatrix->scaleZ = task->amplitude * ((SinFixed(pulsePhase / 4) * 0x3000 /* 3.0 */ >> 12) + 0x1000) >> 12;
    g_BattleSummonIfritPulseMatrix->scaleX = g_BattleSummonIfritPulseMatrix->scaleZ;
    g_BattleSummonIfritPulseMatrix->scaleY = task->amplitude;
    RotMatrix((SVECTOR *)&task->angleX, (PsxMatrix *)g_BattleSummonIfritPulseMatrix);
    g_BattleSummonIfritPulseMatrix->transX = task->posX;
    g_BattleSummonIfritPulseMatrix->transY = task->posY;
    g_BattleSummonIfritPulseMatrix->transZ = task->posZ;
    ScaleMatrix(g_BattleSummonIfritPulseMatrix, &g_BattleSummonIfritPulseMatrix->scaleX);
    MultiplyMatrix(&g_BattleSummonIfritViewMatrix, g_BattleSummonIfritPulseMatrix, g_BattleSummonIfritPulseMatrix);
    SetRotMatrix(g_BattleSummonIfritPulseMatrix);
    SetTransMatrix(g_BattleSummonIfritPulseMatrix);
    SetDrawColorRGB(0, 0, 0);
    g_BattleOverlayDrawListHead = BattleFx_SubmitModelDraw((BattleFxModelDraw *)&g_BattleSummonIfritSpriteDrawReq2, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleOverlayDrawListHead);
    if (g_BattleIsPaused == 0) {
        (task->frame)++;
        task->phase += 0x80;
    }
}

